// Living systems as generative construction: organism to organ systems to organs to tissues to cells to organelles to
// macromolecules to molecules to atoms, with the development relations (gene to protein to behaviour to organism), the
// roles one structure plays in several views (bone: load path, calcium store, blood factory), the reusable mechanisms
// (flight, adhesion, vision, locomotion, thermoregulation, each implemented more than one way), and microbiology with
// its uncertainty marked. Where knowledge is incomplete, the entity says so.
import type { Source } from '../../types';
import { Pack, param } from '../dsl';

const ALBERTS: Source = { cite: 'Alberts et al., Molecular Biology of the Cell, 6th ed., Garland 2015', kind: 'textbook' };
const CAMPBELL: Source = { cite: 'Urry et al., Campbell Biology, 11th ed., Pearson 2017', kind: 'textbook' };
const VOGEL: Source = { cite: 'Vogel, Comparative Biomechanics: Life\'s Physical World, 2nd ed., Princeton 2013', kind: 'textbook' };
