  // nervous
  b('bio.neuron', ['biological', 'component', 'computation'], 'A cell with dendrites, a body and an axon: it sums inputs at synapses and fires an action potential when its threshold is crossed; 1 to 100 m/s along the axon.', { 'is-a': ['bio.cell'], 'has-part': ['bio.axon', 'bio.dendrite', 'bio.synapse', 'bio.ion-channel', 'bio.myelin'], does: ['fn.compute', 'fn.communicate', 'fn.sense'], 'in-view': ['view.neurological', 'view.cellular', 'view.electrical', 'view.informational'], 'governed-by': ['hodgkin-huxley', 'nernst', 'ohm'], 'analogous-to': [['gate.logic', 'a threshold unit'], ['transistor', 'a small signal gating a large current'], ['neuron.artificial', 'the weighted sum it inspired']] }, ALBERTS);
  b('bio.axon', ['biological', 'component'], 'A fibre carrying the action potential: a leaky cable, insulated by myelin, regenerated at nodes.', { 'part-of': ['bio.neuron'], does: ['fn.communicate', 'fn.conduct.current'], 'analogous-to': [['wire', 'an insulated conductor with repeaters'], ['cable', 'signal over distance']], 'governed-by': ['cable.equation', 'hodgkin-huxley'] }, ALBERTS);
