  b('bio.fish-tail', ['biological', 'mechanism'], 'An oscillating foil shedding vortices: thrust by momentum given to water, 80 % propulsive efficiency in tuna.', { does: ['fn.move.fluid'], transforms: ['convert.translational.travel'], 'analogous-to': ['propeller', 'swimmer'], 'governed-by': ['thrust.ideal-static', 'drag.aero', 'strouhal'] }, VOGEL);
  b('bio.flight', ['biological', 'behavior', 'mechanism', 'manifold'], 'Powered flight evolved four times: insects (wings from cuticle, resilin hinges, 200 Hz), pterosaurs (a skin membrane on one finger), birds (feathers on a forelimb), bats (skin between fingers); gliding many more.', { does: ['fn.move'], 'has-part': ['bio.insect-wing-hinge', 'bio.bird-wing', 'bio.bat-wing'], 'governed-by': ['drag.aero', 'thrust.ideal-static', 'allometry'], 'analogous-to': [['vehicle.aircraft', 'a fixed wing with thrust'], ['vehicle.drone', 'flapping and rotary lift'], ['propeller', 'a flapping wing is a propeller unrolled']], 'in-view': ['view.mechanical', 'view.evolutionary'] }, VOGEL);
  b('bio.bird-wing', ['biological', 'mechanism'], 'A forelimb with feathers: an aerofoil that changes shape and area each stroke.', { 'part-of': ['bio.flight'], 'has-part': ['bio.bone', 'bio.feather', 'bio.skeletal-muscle'] }, VOGEL);
  b('bio.bat-wing', ['biological', 'mechanism'], 'Skin stretched between elongated fingers: a membrane wing with many joints.', { 'part-of': ['bio.flight'] }, VOGEL);
  b('bio.adhesion', ['biological', 'mechanism', 'manifold'], 'Sticking to surfaces, several ways: van der Waals forces over a hierarchy of hairs (gecko, dry, reversible), capillary (tree frog, insects), suction (octopus), chemical glue (mussel, barnacle), hooks (burdock, the origin of Velcro).', { does: ['fn.clamp.axial'], 'has-part': ['bio.gecko-adhesion', 'bio.mussel-byssus', 'bio.octopus-sucker', 'bio.burdock-hook'], 'analogous-to': [['adhesive', 'chemical bonding'], ['fastener', 'mechanical hooking'], ['seal', 'suction holds by pressure difference']], 'governed-by': ['van-der-waals', 'hydrostatic'] }, VOGEL);
  b('bio.gecko-adhesion', ['biological', 'mechanism'], 'Half a million setae each splitting into spatulae 200 nm wide: van der Waals attraction summed over them holds a gecko on glass; peeled off by changing the angle.', { 'part-of': ['bio.adhesion'], 'governed-by': ['van-der-waals'], 'analogous-to': ['adhesive'], 'improved-by': [['material.nanomaterial', 'synthetic setae of polymer or nanotube']] }, VOGEL);
  b('bio.octopus-sucker', ['biological', 'mechanism'], 'A muscular cup that pulls a vacuum against the surface.', { 'part-of': ['bio.adhesion'], 'governed-by': ['hydrostatic'], 'analogous-to': ['seal'] }, VOGEL);
  b('bio.burdock-hook', ['biological', 'mechanism'], 'Hooked bracts that catch in fur: copied as Velcro (de Mestral, 1941).', { 'part-of': ['bio.adhesion'], 'analogous-to': ['fastener'] }, VOGEL);
  b('bio.vision', ['biological', 'mechanism', 'manifold'], 'Light sensed and imaged, several architectures: the camera eye (vertebrates, cephalopods, evolved separately), the compound eye (arthropods), the pinhole (nautilus), the mirror eye (scallop), the eyespot (flatworm).', { does: ['fn.sense', 'fn.detect.light'], 'has-part': ['bio.eye-camera', 'bio.compound-eye', 'bio.photoreceptor'], 'analogous-to': ['sensor.camera', 'photodiode'], 'governed-by': ['snell.law', 'rayleigh.resolution', 'planck.energy'], 'in-view': ['view.neurological', 'view.evolutionary'] }, VOGEL);
  b('bio.locomotion', ['biological', 'behavior', 'manifold'], 'Moving the body: walking and running (legs as inverted pendulums and springs), swimming (undulation, foils, jets), flying, crawling (peristalsis), jumping (stored elastic energy), rolling (rare), burrowing.', { does: ['fn.move'], 'has-part': ['bio.flight', 'bio.fish-tail', 'bio.caterpillar-locomotion', 'bio.jumping', 'bio.walking'], 'governed-by': ['froude', 'allometry', 'conservation.energy', 'drag.aero'], 'analogous-to': [['wheel', 'what animals do not grow'], ['track', 'a wave of contact'], ['walker', 'a legged machine']], 'in-view': ['view.mechanical', 'view.behavioral'] }, VOGEL);
  b('bio.walking', ['biological', 'behavior', 'mechanism'], 'The body vaults over a stiff leg (an inverted pendulum, exchanging kinetic and potential energy) at a walk, and bounces on a compliant leg (a spring) at a run; the gait changes at a Froude number near 0.5.', { 'part-of': ['bio.locomotion'], 'governed-by': ['froude', 'pendulum.period', 'spring.energy'], 'analogous-to': ['walker'], 'has-part': ['bio.tendon', 'bio.skeletal-muscle', 'bio.synovial-joint'] }, VOGEL);
  b('bio.jumping', ['biological', 'behavior', 'mechanism'], 'Muscle slowly loads a spring (resilin, tendon, cuticle) and a latch releases it: a flea accelerates at 100 g, a mantis shrimp strikes at 20 m/s.', { 'part-of': ['bio.locomotion'], 'governed-by': ['spring.energy', 'newton.second'], 'analogous-to': [['spring', 'a loaded spring'], ['linkage', 'a latch mechanism'], ['catapult', 'stored elastic energy released']] }, VOGEL);
  b('bio.caterpillar-locomotion', ['biological', 'behavior'], 'A wave of contraction along the body: the rear grips while the front advances.', { 'part-of': ['bio.locomotion'], 'analogous-to': ['track'] }, VOGEL);
  b('bio.rolling-organisms', ['biological', 'behavior'], 'A few animals roll their whole bodies (pangolins, wheel spiders, tumbleweeds); no animal has a free-turning wheel: nothing can feed or innervate a part across a rotating gap.', { 'part-of': ['bio.locomotion'], 'analogous-to': ['wheel'] }, VOGEL);
  b('bio.heat-exchanger', ['biological', 'mechanism'], 'Counter-current blood vessels in flippers, legs and gills: heat (or oxygen) exchanged along the length with little lost.', { 'is-a': ['heat-exchanger'], 'part-of': ['bio.thermoregulation'], 'analogous-to': ['heat-exchanger'] }, VOGEL);
  b('bio.nacre', ['biological', 'material'], 'Aragonite platelets in a protein mortar: mother of pearl, 3000 times tougher than the mineral alone.', { 'is-a': ['material.composite'], 'analogous-to': ['material.composite'], 'produced-by': ['bio.biomineralization'] }, VOGEL);
  b('bio.tree-growth', ['biological', 'process', 'constructor'], 'Cells dividing at the cambium, laying cellulose and lignin in rings: wood made a millimetre a year.', { produces: ['material.wood', 'wood.douglas-fir'], plays: ['role.constructor'], requires: ['bio.photosynthesis', 'element.water', 'chem.nutrient'] }, CAMPBELL);
  b('bio.plant-root', ['biological', 'mechanism'], 'A self-forming anchor growing into the ground, its grip rising with depth and branching.', { does: ['fn.clamp.axial', 'fn.locate'], 'analogous-to': ['woodscrew'] }, CAMPBELL);
  b('bio.stomata', ['biological', 'mechanism'], 'Pores in a leaf opened and closed by two guard cells\' turgor: gas exchange throttled against water loss.', { 'is-a': ['valve'], does: ['fn.control.flow'], 'analogous-to': ['valve'] }, CAMPBELL);
  b('bio.ant-colony', ['biological', 'system'], 'Thousands of ants with no leader: foraging, building and defence emerge from local rules and pheromones.', { 'analogous-to': ['distributed-system', 'algorithm.optimization'], 'in-view': ['view.behavioral', 'view.informational'] }, CAMPBELL);
  b('bio.ant-foraging', ['biological', 'behavior'], 'Trails reinforced by pheromone as ants return with food: the shortest path emerges.', { 'part-of': ['bio.ant-colony'], 'analogous-to': ['algorithm.optimization', 'algorithm.graph'] }, CAMPBELL);
  b('bio.sphincter', ['biological', 'mechanism'], 'A ring of muscle closing a passage.', { 'is-a': ['valve', 'seal'], 'analogous-to': ['seal', 'valve'], 'made-of': ['bio.smooth-muscle'] }, GUYTON);
  b('bio.intervertebral-disc', ['biological', 'component'], 'A gel nucleus in a fibrous ring between vertebrae: a cushion and a joint.', { 'analogous-to': ['damper', 'spring'], plays: ['role.cushion'] }, GRAY);
  b('bio.long-bone', ['biological', 'component'], 'A hollow shaft of cortical bone with cancellous ends: a beam with its material away from the axis.', { 'is-a': ['bio.bone'], 'analogous-to': ['shaft', 'tube.round'], 'governed-by': ['stress.bending'] }, CURREY);
  b('bio.tendon-insertion', ['biological', 'interface'], 'Where a tendon grades into bone through mineralised fibrocartilage: an anchor across a stiffness jump.', { 'analogous-to': ['screw', 'insert.threaded'] }, VOGEL);
  b('bio.tendon-over-pulley', ['biological', 'mechanism'], 'A tendon running over a bony groove or sesamoid: force redirected, as a belt over an idler.', { 'analogous-to': ['belt', 'pulley'] }, VOGEL);
  b('bio.suture', ['biological', 'interface'], 'The interlocking joint between skull bones: formed in place, never undone.', { 'analogous-to': ['rivet'] }, GRAY);
  b('bio.neural-network', ['biological', 'system'], 'Neurons and synapses as a network: the thing the artificial one is named after.', { 'has-part': ['bio.neuron', 'bio.synapse'], 'analogous-to': ['neural-network', 'data-structure.graph'] }, ALBERTS);
  b('bio.metabolic-network', ['biological', 'system'], 'Metabolites and the reactions between them as a graph.', { 'is-a': ['bio.metabolism'], 'analogous-to': ['data-structure.graph'] }, ALBERTS);
  b('bio.biomineralization', ['biological', 'process', 'constructor'], 'Cells laying down mineral in an organic template: bone, teeth, shell, nacre, at room temperature from solution.', { produces: ['bio.bone', 'bio.nacre', 'bio.tooth'], plays: ['role.constructor'], 'analogous-to': [['process.sintering', 'a ceramic made without the heat'], ['process.additive', 'built where the template says']] }, VOGEL);
  b('bio.ossification', ['biological', 'process'], 'Bone made: cartilage replaced by bone (endochondral) or laid directly (intramembranous).', { 'is-a': ['bio.biomineralization'], produces: ['bio.bone'] }, CURREY);
  b('bio.remodelling', ['biological', 'process'], 'Osteoclasts resorb and osteoblasts lay bone where strain says: the skeleton rebuilt every ten years, shaped by its loads (Wolff).', { produces: ['bio.bone'], 'governed-by': ['wolff.law'], 'analogous-to': [['algorithm.optimization', 'topology optimisation by use']] }, CURREY);
  b('bio.tooth', ['biological', 'component', 'material'], 'Enamel (96 % hydroxyapatite, the hardest tissue) over dentine over pulp: a cutting and grinding tool that is not replaced.', { 'made-of': ['material.hydroxyapatite', 'bio.collagen'], plays: ['role.abrasive', 'role.wear-part'], 'analogous-to': ['tool.cutting'], 'produced-by': ['bio.biomineralization'] }, GRAY);

  // microbiology, with uncertainty
  b('bio.bacteria', ['organism', 'biological'], 'Prokaryotes: a cell of 1 µm with no nucleus, a circular genome, a wall, often a flagellum; dividing every 20 minutes when fed; most of the biosphere by number.', { 'has-part': ['bio.cell-membrane', 'bio.cell-wall', 'bio.ribosome', 'bio.dna', 'bio.bacterial-flagellum', 'bio.plasmid'], 'made-of': ['bio.protein', 'bio.lipid', 'bio.nucleic-acid', 'bio.peptidoglycan'], 'reproduced-by': ['bio.cell-division'], 'in-view': ['view.cellular', 'view.ecological'], plays: ['role.constructor', 'role.decomposer'], produces: ['chem.ethanol', 'chem.methane', 'bio.protein', 'material.polymer'], 'interacts-with': ['bio.human', 'bio.immune-system', 'bio.virus', 'earth.soil'], 'fails-by': ['failure.antibiotic'] }, MADIGAN, { unknowns: ['most species are uncultured and known only by their genomes'] });
  b('bio.archaea', ['organism', 'biological'], 'Prokaryotes of a third domain: ether lipids, distinct ribosomes, many in extreme heat, salt and acid; methanogens.', { 'is-a': ['bio.bacteria'], 'has-part': ['bio.cell-membrane', 'bio.ribosome', 'bio.dna'] }, MADIGAN, { unknowns: ['their diversity is mostly unsampled', 'the eukaryote\'s origin among them is debated'] });
  b('bio.fungi', ['organism', 'biological'], 'Eukaryotes digesting outside themselves through chitin-walled hyphae: moulds, yeasts, mushrooms; decomposers and partners of roots.', { 'has-part': ['bio.cell', 'bio.cell-wall', 'bio.chitin', 'bio.hypha'], plays: ['role.decomposer', 'role.constructor'], produces: ['chem.ethanol', 'bio.enzyme', 'material.mycelium'] }, MADIGAN);
  b('bio.protist', ['organism', 'biological'], 'Single-celled eukaryotes of many lineages: amoebae, algae, ciliates, the malaria parasite.', { 'has-part': ['bio.cell', 'bio.nucleus', 'bio.cilia'] }, MADIGAN);
  b('bio.virus', ['biological', 'system'], 'A genome in a protein coat, sometimes a lipid envelope, 20 to 300 nm: no metabolism, it replicates only by a host cell\'s machinery. Whether it is alive is a matter of definition.', { 'has-part': ['bio.virus-capsid', 'bio.viral-genome', 'bio.viral-envelope', 'bio.spike-protein'], 'made-of': ['bio.protein', 'bio.nucleic-acid', 'bio.lipid'], 'reproduced-by': ['bio.viral-replication'], requires: ['bio.cell'], 'interacts-with': ['bio.cell', 'bio.immune-system', 'bio.bacteria'], does: ['fn.remember'], 'in-view': ['view.molecular', 'view.informational'], 'analogous-to': [['program', 'a program with no computer of its own'], ['data-structure', 'information in a package']], 'fails-by': ['failure.antibody-neutralization'] }, FLINT, { unknowns: ['the origin of viruses', 'most of the virosphere is unsequenced'] });
  b('bio.virus-capsid', ['biological', 'component', 'geometry'], 'Identical protein subunits self-assembled into an icosahedron or a helix round the genome.', { 'part-of': ['bio.virus'], 'produced-by': ['bio.self-assembly'], 'analogous-to': [['housing', 'an enclosure'], ['geometry.cellular', 'a shell from repeated units']] }, FLINT);
  b('bio.viral-replication', ['biological', 'process'], 'Attach, enter, uncoat, copy the genome and make the proteins with the host\'s ribosomes, assemble, leave: the host turned into a factory.', { requires: ['bio.cell', 'bio.ribosome', 'bio.receptor'], produces: ['bio.virus'], 'in-view': ['view.molecular'] }, FLINT);
  b('bio.infection', ['biological', 'process'], 'A pathogen entering, multiplying and harming a host, against its immune response.', { 'has-part': ['bio.viral-replication'], 'interacts-with': ['bio.immune-system', 'bio.human'] }, FLINT);
  b('bio.genome', ['biological', 'computation'], 'All of an organism\'s DNA (or a virus\'s RNA): 4.6 million bases in E. coli, 3.2 billion in a human, 150 billion in a lily.', { 'is-a': ['bio.dna'], 'in-view': ['view.informational', 'view.developmental'], 'produced-by': ['bio.replication'], 'analogous-to': ['program', 'memory.flash'] }, ALBERTS);
  // the structures of a body that take part in both the mechanical and the anatomical decompositions, by name
  p.each(['bio.tendon', 'bio.ligament', 'bio.skeletal-muscle', 'bio.heart', 'bio.skin', 'bio.tooth', 'bio.elbow', 'bio.hip-joint', 'bio.sarcomere', 'bio.blood-vessel', 'bio.cortical-bone', 'bio.cancellous-bone', 'bio.exoskeleton', 'bio.skeleton'], { 'in-view': ['view.mechanical', 'view.anatomical'] }, GRAY);
  // the cells and molecules other things are made of
  const bm = (id: string, says: string, links: Parameters<Pack['link']>[1] = {}) => b(id, ['biological', 'material'], says, links);
  bm('bio.albumin', 'The most abundant blood protein: it holds water in the vessels by osmotic pressure and carries fatty acids and hormones.', { 'is-a': ['bio.protein'] });
  bm('bio.cholesterol', 'A lipid in the cell membrane that stiffens and orders it; the precursor of steroid hormones and bile.', { 'is-a': ['bio.lipid'] });
  bm('bio.phospholipid', 'A lipid with a charged head and two fatty tails: it forms the double layer of every membrane.', { 'is-a': ['bio.lipid'] });
  bm('bio.chondrocyte', 'The cell of cartilage: it makes and maintains the proteoglycan and collagen round it, fed by diffusion since cartilage has no vessels.', { 'is-a': ['bio.cell'], 'governed-by': ['fick.diffusion'] });
  bm('bio.fibroblast', 'The cell of connective tissue: it lays down collagen and the matrix, and closes wounds.', { 'is-a': ['bio.cell'] });
  bm('bio.osteoblast', 'The bone-building cell: it lays down collagen and mineralises it.', { 'is-a': ['bio.cell'], 'governed-by': ['wolff.law'] });
  bm('bio.osteoclast', 'The bone-resorbing cell: it dissolves mineral and matrix, remodelling bone to its load.', { 'is-a': ['bio.cell'], 'governed-by': ['wolff.law'] });
  bm('bio.osteocyte', 'A bone cell walled into the matrix: it senses strain and signals the builders and the resorbers.', { 'is-a': ['bio.cell'], 'governed-by': ['wolff.law'] });
  bm('bio.metabolite', 'A small molecule of metabolism, a sugar, an acid, an amino acid, on its way through a pathway.');
  bm('bio.nucleotide', 'A base, a sugar and a phosphate: the unit of DNA and RNA, and as ATP the cell\'s energy currency.');
  bm('bio.peptidoglycan', 'Sugar chains cross-linked by peptides: the bacterial cell wall, which penicillin stops being built.');
  bm('bio.proteoglycan', 'A protein with long charged sugar chains: it draws water into cartilage and resists compression.', { 'is-a': ['bio.protein'] });
  bm('bio.tubulin', 'The protein that polymerises into microtubules: the cell\'s rails and its mitotic spindle.', { 'is-a': ['bio.protein'] });
  // organs, tissues and molecules other things name
  const bc = (id: string, says: string, links: Parameters<Pack['link']>[1] = {}, kinds: Parameters<Pack['e']>[1] = ['biological', 'component']) => b(id, kinds, says, links);
  bc('bio.bone-marrow', 'The soft tissue inside bone: red marrow makes blood cells, two million red cells a second; yellow marrow stores fat.', { 'is-a': ['bio.tissue'], produces: ['bio.red-blood-cell'] });
  bc('bio.blood-vessel', 'A tube of endothelium, muscle and elastin carrying blood: arteries under pressure, veins returning, capillaries one cell thick where the exchange happens.', { 'governed-by': ['bernoulli', 'darcy-weisbach', 'stress.hoop'] });
  bc('bio.cell-wall', 'A rigid layer outside the membrane: cellulose in plants, chitin in fungi, peptidoglycan in bacteria; it holds the turgor pressure that keeps the cell firm.', { 'made-of': ['bio.cellulose', 'bio.peptidoglycan'], 'governed-by': ['hydrostatic'] });
  bc('bio.glia', 'The nervous system\'s other cells, as many as the neurons: they insulate axons with myelin, feed neurons, clear waste and shape synapses.', { 'is-a': ['bio.cell'], does: ['fn.insulate'] });
  bc('bio.hair', 'A keratin fibre grown from a follicle: insulation, sensing, display; 50 to 100 µm thick, growing 0.3 mm a day.', { does: ['fn.insulate', 'fn.sense'], 'governed-by': ['conduction'] });
  bc('bio.lung', 'Two spongy organs of 300 million alveoli, 70 m² of surface a few micrometres from the blood: oxygen in, carbon dioxide out, by diffusion.', { does: ['fn.transfer.oxygen'], 'governed-by': ['fick.diffusion'] });
  bc('bio.pancreas', 'A gland behind the stomach with two jobs: enzymes into the gut to digest, and insulin and glucagon into the blood to set the sugar level.', { 'governed-by': ['michaelis-menten'] });
  bc('bio.spinal-cord', 'The nerve trunk inside the spine: motor commands down, senses up, and reflexes closed within it without the brain.', { does: ['fn.communicate', 'fn.control'], 'governed-by': ['hodgkin-huxley', 'cable.equation'] });
  bc('bio.sweat-gland', 'A coiled tube in the dermis that pumps salt water to the surface: evaporation takes 2.4 MJ per litre, the body\'s main way to shed heat.', { does: ['fn.cool'], 'governed-by': ['clausius-clapeyron'] });
  bc('bio.gamete', 'A sex cell with half the chromosomes, egg or sperm: two fuse to start a new organism.', { 'is-a': ['bio.cell'] });
  bc('bio.mrna', 'Messenger RNA: a copy of a gene carried from the nucleus to the ribosome and read three bases at a time; minutes to hours before it is degraded.', { 'produced-by': ['bio.transcription'] }, ['biological', 'chemical']);
  bc('bio.trna', 'Transfer RNA: an adaptor that carries one amino acid and matches one codon, so the ribosome can read the message into protein.', { 'governed-by': ['michaelis-menten'] }, ['biological', 'chemical']);
  bc('bio.rna-polymerase', 'The enzyme that reads a gene and writes its message: it unwinds the DNA and strings RNA bases along one strand, tens of bases a second.', { 'is-a': ['bio.protein'], 'governed-by': ['michaelis-menten'] }, ['biological', 'mechanism']);
  bc('bio.zygote', 'The one cell an egg and a sperm make: everything an organism becomes starts here, by division and differentiation.', { 'is-a': ['bio.cell'] });
  bc('bio.chloroplast', 'The organelle of photosynthesis: stacked membranes holding chlorophyll, where light is caught and sugar is made, 20 % of a leaf cell.', { transforms: ['convert.optical.chemical'], 'governed-by': ['planck.energy', 'gibbs.energy'] });
  bc('bio.dna-polymerase', 'The enzyme that copies DNA, a thousand bases a second with proofreading: one error in ten million, then repair to one in a billion.', { 'is-a': ['bio.protein'], 'governed-by': ['michaelis-menten'] }, ['biological', 'mechanism']);
  bc('bio.electron-transport-chain', 'Four protein complexes in the mitochondrial membrane passing electrons from food to oxygen and pumping protons as they go: the proton gradient drives ATP synthase.', { 'governed-by': ['nernst', 'gibbs.energy'], transforms: ['convert.chemical.chemical'] }, ['biological', 'mechanism']);
  // the organs, tissues, cells, molecules and processes the systems name
  const bp = (id: string, says: string, links: Parameters<Pack['link']>[1] = {}) => b(id, ['biological', 'process'], says, links);
  const bm2 = (id: string, says: string, links: Parameters<Pack['link']>[1] = {}) => b(id, ['biological', 'chemical'], says, links);
  bc('bio.organism', 'A living thing: one or many cells that take in energy, hold themselves apart from the world, grow, respond and reproduce.', { 'governed-by': ['allometry', 'natural.selection'] }, ['biological', 'organism']);
  bc('bio.organ', 'A part of a body made of several tissues doing one job: a heart, a liver, a lung, a leaf.', { 'is-a': ['bio.tissue'] });
  bc('bio.alveolus', 'One of the lung\'s 300 million air sacs, 0.2 mm across, a single cell thick, wrapped in capillaries: where gas crosses.', { does: ['fn.transfer.oxygen'], 'governed-by': ['fick.diffusion'] });
  bc('bio.trachea', 'The windpipe: a tube held open by rings of cartilage, lined with cilia that sweep dust up and out.', { 'governed-by': ['darcy-weisbach', 'stress.hoop'] });
  bc('bio.diaphragm', 'The sheet of muscle under the lungs: it pulls down, the chest\'s pressure falls, and air comes in; the breath\'s pump.', { 'is-a': ['bio.skeletal-muscle'], 'governed-by': ['ideal.gas', 'hill.muscle'] });
  bc('bio.artery', 'A vessel carrying blood from the heart: thick-walled, elastic, under pressure, smoothing the pulse into the capillaries.', { 'is-a': ['bio.blood-vessel'], 'governed-by': ['stress.hoop', 'bernoulli'] });
  bc('bio.vein', 'A vessel carrying blood back to the heart: thin-walled, low in pressure, with valves so the blood goes one way.', { 'is-a': ['bio.blood-vessel'], 'governed-by': ['hydrostatic'] });
  bc('bio.capillary', 'A vessel one cell thick and a few micrometres wide: the only place blood and tissue exchange, 100 000 km of them in a person.', { 'is-a': ['bio.blood-vessel'], 'governed-by': ['fick.diffusion', 'darcy-weisbach'] });
  bc('bio.coronary-artery', 'The arteries that feed the heart muscle itself: a few millimetres wide, and when one blocks the muscle beyond it dies.', { 'is-a': ['bio.artery'], 'fails-by': ['failure.infarction'] });
  bc('bio.pacemaker-cells', 'The heart\'s own clock: cells in the sinoatrial node that depolarise on their own about once a second and set the beat.', { 'is-a': ['bio.cell'], does: ['fn.oscillate'], 'governed-by': ['hodgkin-huxley'], 'fails-by': ['failure.arrhythmia'] });
  bc('bio.stomach', 'A muscular bag of acid and enzymes: food churned and broken down for hours before it passes on.', { 'governed-by': ['michaelis-menten'] });
  bc('bio.intestine', 'A tube seven metres long whose folds and villi give it the area of a tennis court: digestion finished and the food absorbed.', { does: ['fn.separate'], 'governed-by': ['fick.diffusion'] });
  bc('bio.liver', 'The body\'s chemical plant: it stores sugar as glycogen, makes proteins and bile, and breaks down toxins and old cells; a kilogram and a half.', { 'governed-by': ['michaelis-menten', 'gibbs.energy'] });
  bc('bio.kidney', 'A filter of a million nephrons: 180 litres of blood plasma a day filtered and nearly all of it taken back, the rest as urine.', { does: ['fn.filter'], 'has-part': ['bio.nephron'], 'governed-by': ['fick.diffusion', 'hydrostatic'] });
  bc('bio.nephron', 'The kidney\'s unit: a knot of capillaries that filters, a tube that takes back water, salt and sugar.', { does: ['fn.filter'], 'governed-by': ['fick.diffusion'] });
  bc('bio.bladder', 'A muscular bag that holds urine, half a litre, and empties when told.', { 'governed-by': ['hydrostatic'] });
  bc('bio.gonad', 'The organ that makes gametes, ovary or testis, and the sex hormones with them.', { produces: ['bio.gamete'] });
  bc('bio.adrenal', 'A gland on each kidney: adrenaline for the next few seconds, cortisol for the next few hours.', { produces: ['bio.hormone'] });
  bc('bio.thyroid', 'A gland in the neck whose hormone sets the body\'s metabolic rate, a thermostat for every cell.', { produces: ['bio.hormone'], 'governed-by': ['arrhenius'] });
  bm2('bio.hormone', 'A molecule released into the blood by one organ and read by receptors in others: a slow message to the whole body.', { does: ['fn.communicate'], 'governed-by': ['fick.diffusion', 'michaelis-menten'] });
  bc('bio.lymph-node', 'A filter on the lymph vessels where immune cells meet what the lymph carries, and multiply when they recognise it.', { does: ['fn.filter'] });
  bc('bio.b-cell', 'A white cell that makes antibodies: each clone one shape, multiplied when its shape fits an invader.', { 'is-a': ['bio.cell'], 'governed-by': ['natural.selection'] });
  bc('bio.t-cell', 'A white cell that kills infected cells or directs the others: it reads fragments shown on cell surfaces.', { 'is-a': ['bio.cell'] });
  bc('bio.epidermis', 'The skin\'s outer layer: cells born at the bottom, flattened and filled with keratin, shed from the top a month later.', { 'is-a': ['bio.tissue'], does: ['fn.isolate'] });
  bc('bio.dermis', 'The skin\'s thick inner layer: collagen and elastin, vessels, nerves, glands and follicles; the leather of the hide.', { 'is-a': ['bio.tissue'], 'governed-by': ['hooke'] });
