  bc('bio.nerve', 'A bundle of axons with their sheaths and blood supply, running between the central nervous system and the body.', { does: ['fn.communicate'], 'governed-by': ['cable.equation', 'hodgkin-huxley'] });
  bc('bio.dendrite', 'A neuron\'s branching input: thousands of synapses on it, summed toward the cell body.', { 'governed-by': ['cable.equation'] });
  bm2('bio.myelin', 'Fat wrapped round an axon by glia, in segments: the signal jumps gap to gap, a hundred times faster than bare.', { does: ['fn.insulate'], 'governed-by': ['cable.equation'] });
  bc('bio.motor-neuron', 'The neuron whose axon runs from the spinal cord to a muscle and fires it: the last link of every movement.', { 'is-a': ['bio.neuron'], does: ['fn.control'], 'governed-by': ['hodgkin-huxley'] });
  bc('bio.muscle-fibre', 'One muscle cell, centimetres long, packed with sarcomeres in series and in parallel: it shortens when its motor neuron fires.', { 'is-a': ['bio.cell'], 'governed-by': ['hill.muscle'], 'fails-by': ['failure.tear', 'failure.fatigue-muscle'] });
  bp('bio.training', 'Muscle and bone built by load: fibres thicken after being stressed past their habit, bone densifies where it is strained; use it or lose it.', { 'governed-by': ['wolff.law'] });
  bc('bio.periosteum', 'The membrane on a bone\'s surface: nerves, vessels, and the cells that grow bone outward and heal a break.', { 'is-a': ['bio.tissue'], 'governed-by': ['wolff.law'] });
  bm2('bio.extracellular-matrix', 'What is between the cells: collagen, elastin and proteoglycans that the cells made and live in; the material of a tissue.', { 'made-of': ['bio.collagen-fibre', 'bio.proteoglycan'], 'governed-by': ['hooke'] });
  bm2('bio.collagen-fibre', 'The rope of the body: triple-helix protein wound into fibrils and fibres, strong in tension, in tendon, skin and bone.', { 'is-a': ['bio.protein'], 'governed-by': ['stress.axial'], 'fails-by': ['failure.rupture'] });
  bc('bio.chromosome', 'A DNA molecule wound on proteins into a body a cell can sort: 46 in a human cell, carrying the genome.', { 'made-of': ['bio.dna'] });
  bc('bio.nuclear-pore', 'A gate through the nucleus\'s double membrane: RNA out, proteins in, by their tags.', { does: ['fn.filter'] });
  bc('bio.cytoplasm', 'Everything inside the cell membrane but the nucleus: water, salts, proteins, organelles, a crowded gel.', { 'governed-by': ['fick.diffusion'] });
  bc('bio.endoplasmic-reticulum', 'Folded membranes through the cell: ribosomes on the rough part make proteins into it, the smooth part makes lipids.', { does: ['fn.construct'] });
  bc('bio.golgi', 'The cell\'s post office: proteins sorted, tagged and packed into vesicles for where they are going.', { does: ['fn.separate'] });
  bc('bio.lysosome', 'A bag of acid enzymes inside the cell: what is worn out or swallowed is taken apart here.', { 'governed-by': ['michaelis-menten'] });
  bm2('bio.mitochondrial-dna', 'The mitochondrion\'s own small genome, 37 genes, inherited from the mother alone: a relic of the bacterium it was.', { 'is-a': ['bio.dna'] });
  bp('bio.citric-acid-cycle', 'The wheel of reactions in the mitochondrion that burns acetyl groups to carbon dioxide and loads the carriers that drive ATP synthesis.', { 'governed-by': ['michaelis-menten', 'gibbs.energy'] });
  bm2('bio.glycogen', 'Glucose stored as a branched chain in liver and muscle: a day\'s fuel, mobilised in minutes.', { does: ['store.energy'], 'governed-by': ['gibbs.energy'] });
  bm2('bio.transporter', 'A membrane protein that carries a molecule across: with the gradient for free, against it at the cost of ATP.', { 'is-a': ['bio.protein'], 'governed-by': ['fick.diffusion', 'michaelis-menten'] });
  bm2('bio.protein-complex', 'Several proteins assembled into one machine: a ribosome, ATP synthase, the electron transport chain.', { 'is-a': ['bio.protein'] });
  bm2('bio.microtubule', 'A hollow rod of tubulin, 25 nm across: the cell\'s scaffold and rail, assembled and taken down as needed.', { 'made-of': ['bio.tubulin'], 'governed-by': ['buckling.euler'] });
  bm2('bio.dynein', 'A motor protein that walks along microtubules, bending cilia and hauling cargo, one ATP a step.', { 'is-a': ['bio.protein'], does: ['fn.move'], 'governed-by': ['michaelis-menten'] });
  bm2('bio.flagellin', 'The protein that polymerises into a bacterium\'s flagellum: a hollow helical filament the motor spins.', { 'is-a': ['bio.protein'] });
  bc('bio.plasmid', 'A small ring of DNA in a bacterium apart from its chromosome, copied and passed between cells: how resistance spreads.', { 'made-of': ['bio.dna'], 'governed-by': ['natural.selection'] });
  bc('bio.hypha', 'A fungus\'s thread: a tube of cells a few micrometres wide growing at its tip through soil or wood, digesting outside itself.', { 'is-a': ['bio.cell'] });
  bm2('bio.viral-genome', 'A virus\'s few genes, DNA or RNA, enough to make copies of itself in a cell that does the work.', {});
  bm2('bio.viral-envelope', 'The lipid coat some viruses take from the cell they leave, studded with their own proteins.', { 'made-of': ['bio.lipid'] });
  bm2('bio.spike-protein', 'The protein on a virus\'s surface that binds the receptor of the cell it enters: the key, and what antibodies are made against.', { 'is-a': ['bio.protein'], 'fails-by': ['failure.antibody-neutralization'] });
  bc('bio.feather', 'Keratin branched into a vane that zips together: light, stiff, and shaped for lift or warmth.', { does: ['fn.insulate'], 'governed-by': ['drag.aero'] });
  bc('bio.cork', 'The bark of the cork oak as the tree makes it: dead cells with waxy walls, a closed-cell foam that keeps water in and fire out.', { 'is-a': ['material.cork'] });
  bc('bio.wood', 'Wood as the tree grows it: cellulose fibres in lignin laid down in rings, stiff along the grain, the composite that holds a tree up.', { 'is-a': ['material.wood'] });
