  bp('bio.adaptation', 'A trait shaped by selection to fit its environment: the heritable result of what survived.', { 'governed-by': ['natural.selection'] });
  bp('bio.differentiation', 'A cell taking on its kind: the same genome, a different set of genes switched on, by signals from its neighbours.', { 'governed-by': ['hebb.rule'] });
  bp('bio.morphogenesis', 'A shape made by cells: growing, moving, dividing and dying in patterns set by gradients of signals.', { 'governed-by': ['fick.diffusion', 'allometry'] });
  return p;
